INSERT INTO entity_citations (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order) VALUES
('CIT_EGY_DEDWEN_PYRAMI','ENT_EGY_DEDWEN','SRC_FAULKNER_PYRAMID_TEXTS','The Ancient Egyptian Pyramid Texts (Faulkner)','The Ancient Egyptian Pyramid Texts (Faulkner)','Dedwen (ddwn). God of Nubia and Nubian incense. Delta (mœw "immersed"). Triangular portion of the Nile basin between modern Cairo and the Mediterranean, where the Nile divides into sev- eral branches; in ancient times largely marshland. Dendera (jwnt). Town on the west bank of the Nile north of modern Luxor, chief cult center of Hathor. Dep. See Buto. Dilapidated One (szaew). Perhaps an epithet of Horus, referring to the loss of his eye. Director (arp).','R. O. Faulkner',1969,'None',NULL,'primary-verbatim',NULL,true,'In-copyright modern translation — brief excerpt for identification, located by name; verify Utterance against the edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_EGY_DUAMUTEF_PYRAMI','ENT_EGY_DUAMUTEF','SRC_FAULKNER_PYRAMID_TEXTS','The Ancient Egyptian Pyramid Texts (Faulkner)','Utterance 552:','Duamutef (dwae-mjwt.f "He Whom His Mother Worships"). One of the four children of Horus, representing the cardinal direction east. Duat (dwaet). Term for the region through which the Sun travels at night, seen both as the womb of Nut and a space beneath the earth. In the Pyramid Texts, associated with the burial chamber of the pyramid. Duat Lake (sj dwaetj). A portion of the night sky. Edfu (ybaewtj).','R. O. Faulkner',1969,'None',NULL,'primary-verbatim',NULL,true,'In-copyright modern translation — brief excerpt for identification, located by name; verify Utterance against the edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_EGY_FOUR_SONS_OF_HORUS_PYRAMI','ENT_EGY_FOUR_SONS_OF_HORUS','SRC_FAULKNER_PYRAMID_TEXTS','The Ancient Egyptian Pyramid Texts (Faulkner)','Utterance 552','Within Nut''s womb, he embodied the force through which the Sun received the power of new life, to appear at dawn as Osiris reborn in his own son, the god Horus. As the primary force of the Duat, Osiris was also seen as its king, ruler of this region and its inhabitants.','R. O. Faulkner',1969,'None',NULL,'primary-verbatim',NULL,true,'In-copyright modern translation — brief excerpt for identification, located by name; verify Utterance against the edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_EGY_HAPY_SON_OF_HORUS_PYRAMI','ENT_EGY_HAPY_SON_OF_HORUS','SRC_FAULKNER_PYRAMID_TEXTS','The Ancient Egyptian Pyramid Texts (Faulkner)','Utterance 552:','Within Nut''s womb, he embodied the force through which the Sun received the power of new life, to appear at dawn as Osiris reborn in his own son, the god Horus. As the primary force of the Duat, Osiris was also seen as its king, ruler of this region and its inhabitants.','R. O. Faulkner',1969,'None',NULL,'primary-verbatim',NULL,true,'In-copyright modern translation — brief excerpt for identification, located by name; verify Utterance against the edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_EGY_HATHOR_PYRAMI','ENT_EGY_HATHOR','SRC_FAULKNER_PYRAMID_TEXTS','The Ancient Egyptian Pyramid Texts (Faulkner)','Utterance 247','Hathor (œwt-œrw "Horus''s Enclosure"). The principle of joy, feminine love, and motherhood. As a goddess, her primary role was as the mother and wife of Horus. Also associated with the West and therefore func- tioned as mother of the deceased. He in the Wrappings (jmj-wt). An epithet and fetish of Anubis in his role as god of mummification. He of the Height (qaetj).','R. O. Faulkner',1969,'None',NULL,'primary-verbatim',NULL,true,'In-copyright modern translation — brief excerpt for identification, located by name; verify Utterance against the edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_EGY_KHEPRI_PYRAMI','ENT_EGY_KHEPRI','SRC_FAULKNER_PYRAMID_TEXTS','The Ancient Egyptian Pyramid Texts (Faulkner)','Utterance 600','Designation of the Sun as he comes into being ("evolves") at dawn; the Egyptian name is also vocalized as Khepri. Experienced. God of woodworking; also, an epithet of Osiris. Eyes-Forward (antj-jrtj). Falcon-headed god of Letopolis, a form of Horus as celestial deity. The Egyptian name is also vocalized as Khentiirti. External Isles (œaew-nbwt). The islands of the Mediterranean Sea. Face Behind Him (œr.f-œae.f).','R. O. Faulkner',1969,'None',NULL,'primary-verbatim',NULL,true,'In-copyright modern translation — brief excerpt for identification, located by name; verify Utterance against the edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_EGY_KHNUM_PYRAMI','ENT_EGY_KHNUM','SRC_FAULKNER_PYRAMID_TEXTS','The Ancient Egyptian Pyramid Texts (Faulkner)','The Ancient Egyptian Pyramid Texts (Faulkner)','Southernmost town of ancient Egypt, part of modern Aswan; cult center of Khnum and Satis, and of Osiris as the life-giving power in the inundation. Elite (pet). The ruling class of Egypt, consisting of the royal family and governmental officials; also, the same concept applied to the gods. Enclosure (œwt). General term for any complex of one or more buildings surrounded by an enclosure wall; most often, a temple. Enclosure of Gold (œwt nbw).','R. O. Faulkner',1969,'None',NULL,'primary-verbatim',NULL,true,'In-copyright modern translation — brief excerpt for identification, located by name; verify Utterance against the edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_EGY_MONTU_PYRAMI','ENT_EGY_MONTU','SRC_FAULKNER_PYRAMID_TEXTS','The Ancient Egyptian Pyramid Texts (Faulkner)','The Ancient Egyptian Pyramid Texts (Faulkner)','GLOSSARY 437 Montu (mniw). Principle of aggressiveness, represented as a falcon or bull; his chief cult-center was Armant, south of modern Luxor. Mooring Post (mjnt), Moorer (smntt). Two unidentified constellations of the northern or northwestern sky, envisioned as a mooring post and a hippopotamus driving it into the ground. Morning God (dwaew, nir dwae). Designation of the planet Venus, associated with Horus as a harbinger of the sunrise. Mound (jaet).','R. O. Faulkner',1969,'None',NULL,'primary-verbatim',NULL,true,'In-copyright modern translation — brief excerpt for identification, located by name; verify Utterance against the edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_EGY_NEKHBET_PYRAMI','ENT_EGY_NEKHBET','SRC_FAULKNER_PYRAMID_TEXTS','The Ancient Egyptian Pyramid Texts (Faulkner)','Utterance 508','Nekhbet (nabt "She of Nekhbet"). Vulture goddess whose cult-center was at Nekheb, tutelary goddess of Upper Egypt. Nekheb (nab). Town in Upper Egypt, modern el-Kab, opposite and twin to Nekhen. Nekhen (nan). Town in Upper Egypt opposite Nekheb, also known as Hierakonpolis. Earliest center of Egyptian royal power and cult center of Horus as god of kingship. Nephthys (nbt-œwt "Lady of the Enclosure").','R. O. Faulkner',1969,'None',NULL,'primary-verbatim',NULL,true,'In-copyright modern translation — brief excerpt for identification, located by name; verify Utterance against the edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_EGY_OGDOAD_PYRAMI','ENT_EGY_OGDOAD','SRC_FAULKNER_PYRAMID_TEXTS','The Ancient Egyptian Pyramid Texts (Faulkner)','The Ancient Egyptian Pyramid Texts (Faulkner)','The Ogdoad''s theological center was Hermopolis, whose chief god, Thoth, was also its "Lord." Old Kingdom. The period of ancient Egyptian history between the begin- ning of Dyn. III (ca. 2650 B.C.) and the end of Dyn. VIII (ca. 2100 B.C.). Ombos (nbwt). Town in Upper Egypt, north of Qus. Its chief god, Seth, was called "the Ombite" (nbwtj). Orion (saeœ). Identical with the modern constellation, associated with Osiris. Osiris (js-jrt "seat of the eye").','R. O. Faulkner',1969,'None',NULL,'primary-verbatim',NULL,true,'In-copyright modern translation — brief excerpt for identification, located by name; verify Utterance against the edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_EGY_QEBEHSENUEF_PYRAMI','ENT_EGY_QEBEHSENUEF','SRC_FAULKNER_PYRAMID_TEXTS','The Ancient Egyptian Pyramid Texts (Faulkner)','Utterance 552:','um is for the four gods that Horus gave birth to and desired, Hapi, Imseti, Duamutef, and Qebehsenuef; his head, his tail, his arms, and his legs are for the two of Anubis-town, Osiris and Thighs-Forward; and what the gods leave of him is for the bas of Nekhen and the bas of Pe. The eaten one to be eaten, the red ox, is for the lake journey that Horus has made for his father, this Osiris Pepi. 523 RECITATION.','R. O. Faulkner',1969,'None',NULL,'primary-verbatim',NULL,true,'In-copyright modern translation — brief excerpt for identification, located by name; verify Utterance against the edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_EGY_SESHAT_PYRAMI','ENT_EGY_SESHAT','SRC_FAULKNER_PYRAMID_TEXTS','The Ancient Egyptian Pyramid Texts (Faulkner)','Utterance 616','Seshat (ssaet). Goddess of record-keeping, archives, and building. A unique male form of this deity, Seshau, appears in Unis''s Spell 191. Seth (sto). The principle of male sexuality and wild, disordered behavior; god of deserts and storms; son of Geb and Nut, husband of Nephthys; represented by an unidentified animal.','R. O. Faulkner',1969,'None',NULL,'primary-verbatim',NULL,true,'In-copyright modern translation — brief excerpt for identification, located by name; verify Utterance against the edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_EGY_SOBEK_PYRAMI','ENT_EGY_SOBEK','SRC_FAULKNER_PYRAMID_TEXTS','The Ancient Egyptian Pyramid Texts (Faulkner)','Utterance 317','My father102 has inherited from Horus as Horus in Seal-ring, Seth in the Ennead, Sobek in [Shedit]. Let arms beat, let drumming go down! 152 THE ANCIENT EGYPTIAN PYRAMID TEXTS The great Mooring-Post will call out to [you]; your sister Nephthys will come [to] you, your sister Isis will clean for you; your mother, the sky, will go down for you. The women of Buto will come to you and put termini at [ ... ] for you [ ... ] with the Imperishable Stars. [ ...','R. O. Faulkner',1969,'None',NULL,'primary-verbatim',NULL,true,'In-copyright modern translation — brief excerpt for identification, located by name; verify Utterance against the edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_EGY_TEFNUT_PYRAMI','ENT_EGY_TEFNUT','SRC_FAULKNER_PYRAMID_TEXTS','The Ancient Egyptian Pyramid Texts (Faulkner)','Utterance 600','Originally, the nine gods incorporating the physical creation of the world: Atum; Shu and Tefnut; Geb and Nut; Osiris and Isis, Seth 430 THE ANCIENT EGYPTIAN PYRAMID TEXTS and Nephthys, known as the Big Ennead (pyt eaet); also a term for any number of gods conceived as a group, and for all the gods as a whole.','R. O. Faulkner',1969,'None',NULL,'primary-verbatim',NULL,true,'In-copyright modern translation — brief excerpt for identification, located by name; verify Utterance against the edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_EGY_WADJET_PYRAMI','ENT_EGY_WADJET','SRC_FAULKNER_PYRAMID_TEXTS','The Ancient Egyptian Pyramid Texts (Faulkner)','The Ancient Egyptian Pyramid Texts (Faulkner)','Nekhbet and Wadjet, the tutelary goddesses of Egypt and the king. The former was represented as a vulture; the latter, as a cobra. Two Lands (taewj). Political designation of Egypt as the union of the Nile Valley and Delta. Two Lords (nbwj). Seth and Horus, representing opposing forces, united in the person of the living king. Two Shores (jdbwj). Upper Egypt as the land on either side of the Nile. Undersky (nwt, nnwt).','R. O. Faulkner',1969,'None',NULL,'primary-verbatim',NULL,true,'In-copyright modern translation — brief excerpt for identification, located by name; verify Utterance against the edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_EGY_WENEG_PYRAMI','ENT_EGY_WENEG','SRC_FAULKNER_PYRAMID_TEXTS','The Ancient Egyptian Pyramid Texts (Faulkner)','The Ancient Egyptian Pyramid Texts (Faulkner)','Horus''s path, make your tent to Teti, make your arms to Teti! Sun, come, ferry Teti to the other side like your ferrying of your fol- lower Weneg, whom you love. Whenever you give your arm toward the west, you give your arm toward Teti; whenever you give your arm toward the east, you give your arm toward Teti-like that which you have done for Benti, your senior son. 186 RECITATION. Do not be ignorant of Teti, god, since he knows you.','R. O. Faulkner',1969,'None',NULL,'primary-verbatim',NULL,true,'In-copyright modern translation — brief excerpt for identification, located by name; verify Utterance against the edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1),
('CIT_EGY_WEPWAWET_PYRAMI','ENT_EGY_WEPWAWET','SRC_FAULKNER_PYRAMID_TEXTS','The Ancient Egyptian Pyramid Texts (Faulkner)','Utterance 468','The Egyptian name is usually vocalized as Wepwawet. Pavilion-director (arp-zœ). Official in charge of the dining hall. Pe. See Buto. Pe''s Seal-ring. See Seal-ring. Peace-Commander (wy-œtp). An epithet of Khnum. Pebble Mountain (enw, enwt). Mountain region in which the sun rises. Pelusium (snw). Town at the end of the easternmost Delta branch of the Nile in ancient times. Perception (sjae).','R. O. Faulkner',1969,'None',NULL,'primary-verbatim',NULL,true,'In-copyright modern translation — brief excerpt for identification, located by name; verify Utterance against the edition.',DATE '2026-06-18','name-anchored (note-keyword scored) + substring gate; locus per attestation',1)
